{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE snitch_db.maplemonk.gs_wh_union AS SELECT * FROM snitch_db.maplemonk.gs__wh1_oct UNION ALL SELECT * FROM snitch_db.maplemonk.gs__wh1_nov UNION ALL SELECT * FROM snitch_db.maplemonk.gs__wh1_dec UNION ALL SELECT * FROM snitch_db.maplemonk.gs__wh2_oct UNION ALL SELECT * FROM snitch_db.maplemonk.gs__wh2_nov UNION ALL SELECT * FROM snitch_db.maplemonk.gs__wh2_dec UNION ALL SELECT * FROM snitch_db.maplemonk.gs_emiza_rto UNION ALL SELECT * FROM snitch_db.maplemonk.gs_emiza_dto; create or replace table snitch_db.maplemonk.gs_wh_returns as WITH ReturnsCTE AS ( SELECT TO_DATE(receiving_date, \'DD/MM/YYYY\') AS receiving_date, TO_DATE(processing_date, \'DD/MM/YYYY\') AS processing_date, UPPER(CAST(awb_number AS TEXT)) AS awb_number, CAST(scanning_done AS TEXT) AS scanning_done, CAST(name AS TEXT) AS name, CAST(warehouse AS TEXT) AS warehouse, CAST(channel AS TEXT) AS channel, CAST(\"rto/dto\" AS TEXT) AS rto_dto, CAST(logistics AS TEXT) AS logistics, CAST(qc_status AS TEXT) AS qc_status, CAST(count AS INTEGER) AS count, CAST(packet AS TEXT) AS packet, DATEDIFF(DAY, TO_DATE(receiving_date, \'DD/MM/YYYY\'), TO_DATE(processing_date, \'DD/MM/YYYY\')) AS processing_days FROM snitch_db.maplemonk.gs_wh_union WHERE awb_number IS NOT NULL ), LatestReversePickup AS ( SELECT rp.\"Tracking No\", rp.\"Channel Name\", rp.\"Sale Order Item Code\", rp.\"Original Sale Order Code\", rp.\"Reverse Pickup Status\", rp.\"Return Delivery Date\", rp.\"Putaway Last Updated\", rp.\"Reverse Pickup Last Updated\" AS processed_date, ROW_NUMBER() OVER (PARTITION BY rp.\"Tracking No\" ORDER BY rp.\"Reverse Pickup Last Updated\" DESC) AS row_num FROM snitch_db.maplemonk.snitch_get_copy_of_reverse_pickup rp ), FilteredReversePickup AS ( SELECT \"Tracking No\", \"Channel Name\", \"Sale Order Item Code\", \"Original Sale Order Code\", \"Reverse Pickup Status\", \"Return Delivery Date\", \"Putaway Last Updated\", processed_date FROM LatestReversePickup WHERE row_num = 1 ) SELECT r.receiving_date, r.processing_date, r.awb_number, r.scanning_done, r.name, r.warehouse, r.channel, r.rto_dto, r.logistics, r.qc_status, r.count, r.packet, r.processing_days, case when rp.\"Putaway Last Updated\" < rp.processed_date THEN rp.\"Putaway Last Updated\" else rp.processed_date end as revised_processed_date, CASE WHEN r.rto_dto = \'DTO\' THEN rp.\"Tracking No\" ELSE cr.\"AWB No\" END AS tracking_number, COALESCE(rp.\"Reverse Pickup Status\", cr.\"Return Status\") AS return_status, TO_TIMESTAMP( COALESCE( NULLIF(revised_processed_date, \'\'), NULLIF(cr.\"Return Date\", \'\'), NULL ) ) AS \"Processed Date\", TO_TIMESTAMP( COALESCE( NULLIF(rp.\"Return Delivery Date\", \'\'), NULLIF(cr.\"Return Delivery Date\", \'\'), r.receiving_date ) ) AS RDD, DATEDIFF( DAY, CAST( COALESCE( NULLIF(rp.\"Return Delivery Date\", \'\'), NULLIF(cr.\"Return Delivery Date\", \'\'), r.receiving_date ) AS DATE ), CAST( COALESCE( NULLIF(revised_processed_date, \'\'), NULLIF(cr.\"Return Date\", \'\'), r.processing_date ) AS DATE ) ) AS UCprocessing_days, coalesce(rp.\"Channel Name\",cr.\"Channel Name\") as Marketplace, coalesce(rp.\"Sale Order Item Code\",cr.\"Sale Order Item\") as SaleOrderItemCode, coalesce(rp.\"Original Sale Order Code\",cr.\"Sale Order No\") as order_id, FROM ReturnsCTE r LEFT JOIN FilteredReversePickup rp ON r.awb_number = rp.\"Tracking No\" LEFT JOIN snitch_db.maplemonk.snitch_db_get_courier_returns_itemwise_new cr ON r.awb_number = cr.\"AWB No\"; SELECT r.*, rp.\"Tracking No\", rp.\"Channel Name\", rp.\"Sale Order Item Code\", rp.\"Original Sale Order Code\", rp.\"Reverse Pickup Status\", rp.\"Return Delivery Date\", rp.\"Reverse Pickup Last Updated\" FROM snitch_db.maplemonk.gs_wh_returns r LEFT JOIN snitch_db.maplemonk.snitch_get_copy_of_reverse_pickup rp ON r.SaleOrderItemCode = rp.\"Sale Order Item Code\";",
                    "transaction": true
                }
            ) }}
